//! Single TimeMap conversion steps, checked against the C library.
//!
//! `time_map_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/time_map_probe.c`. Each case is a TimeMap holding
//! one step, applied to two points in both directions without
//! simplification, so it pins the step arithmetic of timemap.c `Transform`
//! and the arguments `AddArgs` derives. Every step is run with points that
//! are small offsets from an MJD offset of 55000.5, and with absolute
//! points and zero offsets, as TimeFrame uses a TimeMap to re-express a
//! TimeOrigin.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "time_map_oracle/cases.rs"]
mod cases;

use starlink_ast::coords::PointSet;
use starlink_ast::mappings::{Mapping, TimeCvtType, TimeMap};

fn apply(map: &TimeMap, points: [f64; 2], forward: bool) -> [f64; 2] {
    let pts = PointSet::from_columns(&[&points[..]]).unwrap();
    let out = map.transform(&pts, forward).unwrap();
    [out.point(0)[0], out.point(1)[0]]
}

#[test]
fn steps_match_the_c_library() {
    let failures: Vec<String> = cases::CASES
        .iter()
        .flat_map(|&(name, code, args, points, fwd, inv)| {
            let cvt = TimeCvtType::from_code(code).expect("known conversion code");
            let mut map = TimeMap::new();
            map.add(cvt, args).unwrap();
            let got_fwd = apply(&map, points, true);
            let got_inv = apply(&map, points, false);
            [
                (got_fwd != fwd)
                    .then(|| format!("{name} forward: got {got_fwd:?}, C gives {fwd:?}")),
                (got_inv != inv)
                    .then(|| format!("{name} inverse: got {got_inv:?}, C gives {inv:?}")),
            ]
        })
        .flatten()
        .collect();
    assert!(
        failures.is_empty(),
        "{} of {} directions differ from C:\n{}",
        failures.len(),
        2 * cases::CASES.len(),
        failures.join("\n")
    );
}
